
/*
* UNIFIED SERVICE WORKER
* This file acts as the primary entry point for both PWA (next-pwa) and Firebase FCM.
*/

importScripts('https://www.gstatic.com/firebasejs/10.7.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.7.1/firebase-messaging-compat.js');

// 1. IMPORT PWA SERVICE WORKER (Generated by next-pwa)
// We wrap it in a try-catch to ensure Firebase works even if precaching fails
try {
  importScripts('/sw.js');
  console.log('FCM SW: PWA sw.js imported successfully.');
} catch (e) {
  console.warn('FCM SW: PWA sw.js could not be loaded. This might happen in development or if build files are missing.', e);
}

// 2. INITIALIZE FIREBASE (Compat Version for SW)
// These values are public and safe to include in the SW file.
const firebaseConfig = {
  apiKey: "AIzaSyAogMOncvmZLqQ1qom0d3RDihdqOB9XRiY", // Standard Firebase public keys
  authDomain: "studyscript.firebaseapp.com",
  projectId: "studyscript",
  storageBucket: "studyscript.firebasestorage.app",
  messagingSenderId: "891979418045",
  appId: "1:891979418045:web:047bfd8a00e148c14dead4"
};

// Note: Use environment variables or global replacements during build if needed.
// For now, initializing with project context from the hook registration is sufficient.
if (!firebase.apps.length) {
    firebase.initializeApp(firebaseConfig);
}

const messaging = firebase.messaging();

// 3. HANDLE BACKGROUND NOTIFICATIONS
messaging.onBackgroundMessage((payload) => {
  console.log('FCM SW: Received background message: ', payload);

  const notificationTitle = payload.data.title || "StudyScript Update";
  const notificationOptions = {
    body: payload.data.body || "New content available!",
    icon: payload.data.icon || '/icons/icon-192x192.png',
    data: {
      url: payload.data.link || '/'
    }
  };

  return self.registration.showNotification(notificationTitle, notificationOptions);
});

// 4. HANDLE NOTIFICATION CLICK
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const urlToOpen = event.notification.data.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (let i = 0; i < windowClients.length; i++) {
        const client = windowClients[i];
        if (client.url === urlToOpen && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});
